const abiertas = {};

/** Devuelve { tam, glifos, alfa (Buffer) } de una fuente: "serif", "italica" o "mono". */
export function fuente(clave) {
  const f = FUENTES[clave] || FUENTES.serif;
  const k = FUENTES[clave] ? clave : "serif";
  if (!abiertas[k]) abiertas[k] = { tam: f.tam, glifos: f.glifos, alfa: inflateSync(Buffer.from(f.datos, "base64")) };
  return abiertas[k];
}
